INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-c9ec-7e5f-8d36-255481374b5f'::uuid, '019f9df7-a2a2-7941-9e48-3d4dda1f252c'::uuid, 'A school has 50 students. The probability that a student joins the drama club is 0.44. Two students are selected without replacement. Find the probability that both selected students belong to the drama club.', '33/175', 'Drama students = 0.44 × 50 = 22. P(both) = (22/50) × (21/49) = 462/2450 = 33/175.', 'Medium', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:40.364Z'::timestamptz, '2026-08-15T07:50:40.364Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-c9f7-708a-be56-d22ad06ef1bb'::uuid, '019f9df7-a2a2-78fc-bd9e-a40e9b4f9363'::uuid, 'A car tyre has a rim diameter of 18 inches. The tyre width is 225 mm and its sidewall height is 55% of its width. Using 1 inch = 2.54 cm, find the circumference of the tyre in metres.', '2.21 m', 'Rim diameter = 18 × 2.54 = 45.72 cm. Sidewall = 0.55 × 22.5 = 12.375 cm. Total diameter = 45.72 + 2(12.375) = 70.47 cm = 0.7047 m. Circumference = π(0.7047) ≈ 2.21 m.', 'Hard', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:40.374Z'::timestamptz, '2026-08-15T07:50:40.374Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-ca00-7139-9345-e75bcf2e1e3a'::uuid, '019f9df7-a2a2-7853-96ff-2c02dc5e1f10'::uuid, 'A test tube contains 12 bacteria initially, and the number doubles every day. Find the number of bacteria after 7 days.', '1536', 'Number after 7 days = 12 × 2⁷ = 12 × 128 = 1536.', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:40.383Z'::timestamptz, '2026-08-15T07:50:40.383Z'::timestamptz) ON CONFLICT (id) DO NOTHING;